using System.Text.Json;
namespace TechMove.Web.Services;
public class CurrencyService(HttpClient httpClient) { private const string Endpoint = "https://open.er-api.com/v6/latest/USD"; public async Task<decimal> GetUsdToZarRateAsync(CancellationToken cancellationToken = default) { using var response = await httpClient.GetAsync(Endpoint, cancellationToken); response.EnsureSuccessStatusCode(); await using var stream = await response.Content.ReadAsStreamAsync(cancellationToken); using var json = await JsonDocument.ParseAsync(stream, cancellationToken: cancellationToken); var root = json.RootElement; if (root.TryGetProperty("result", out var result) && result.GetString() != "success") throw new InvalidOperationException("Currency API did not return success."); if (!root.TryGetProperty("rates", out var rates) || !rates.TryGetProperty("ZAR", out var rate)) throw new InvalidOperationException("USD-to-ZAR rate was not returned by the currency API."); return rate.GetDecimal(); } }